#!/usr/bin/env python3

###
# Adds a FORCE_ACTIVE block to the linker script generated by dsd.
# Library functions that the original game keeps without any caller would otherwise be
# removed by `mwldarm -dead` (mwldarm only accepts a handful of -force_active flags).
# Usage: lcf_force_active.py <in.lcf> <libs/build_settings.json> <out.lcf>
###

import json
import sys
from pathlib import Path

lcf_in, settings_path, lcf_out = (Path(arg) for arg in sys.argv[1:4])
lcf = lcf_in.read_text()
symbols = json.loads(settings_path.read_text()).get("force_active", [])
if symbols:
    block = "FORCE_ACTIVE {\n" + ",\n".join(f"    {name}" for name in symbols) + "\n}\n\n"
    if "KEEP_SECTION {" not in lcf:
        sys.exit("lcf_force_active.py: KEEP_SECTION block not found in " + str(lcf_in))
    lcf = lcf.replace("KEEP_SECTION {", block + "KEEP_SECTION {", 1)
lcf_out.write_text(lcf)
